raw:
{
  "spells": [
    {
      "id": "spell_space_04",
      "theory": "锁隙术把魔力压入门锁机械的间隙，使锁舌与扣板之间的空隙被临时填实，形成一层极薄的固化层。这层固化只作用于原有缝隙，不改变锁具结构，也不产生新锁点。施术者需能看见锁体或通过相连的门板感知其位置。施术完成后，只有配对的真实钥匙才能顶开固化层并正常转动锁芯。",
      "casting": "以食指与中指并拢，隔空沿锁缝走向划一条直线，同时将魔力从指尖缓缓推入缝隙，直到听见细微的吱声后收手。",
      "failure": "魔力未能均匀填满缝隙时，锁芯会卡在半转位置，钥匙插不进也拔不出。间隙过大的旧锁可能只固化一半，锁舌仍可被拨动，但会发出滞涩的金属摩擦声。",
      "counters": [
        "用细钢丝探入锁缝，沿固化层边缘撬动即可使其碎裂。",
        "对锁体浇灌热水使金属膨胀，固化层会因挤压而剥落。"
      ],
      "socialConsequences": "河谷乡约常请会此术的人为粮仓和祠堂锁具加护，但要求施术前当众说明用途，避免私占他人门锁。中陆城市公会仓库管理人也愿意雇佣这类术者，却坚持登记施术时间与锁具编号。琥珀海岸的船主担心有人趁夜固化货舱锁以拖延卸货，因此港口更夫会巡查锁缝是否有异样光泽。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时固化层厚薄不均，钥匙需反复转动才能开锁。",
        "掌握均匀推送后，锁具可被正常钥匙一次开启。",
        "熟练者能按锁缝宽度调整魔力，减少金属表面的残留。",
        "更高熟练度使固化层更薄更稳，仍只作用于原有锁隙。"
      ]
    },
    {
      "id": "spell_space_05",
      "theory": "取回线在施术者与视野内某件自有轻物之间拉出一条极细的魔力牵引线，牵引线不穿过实体障碍，只沿视线可达的路径延伸。物品需为施术者本人所有或明确受托保管，且重量在轻物范围内。牵引线收紧时物品沿原路返回，途中若被他人握持或压住，牵引线会滑动而非强行夺走。",
      "casting": "伸出惯用手，掌心朝向目标，拇指与中指相触成环，再缓缓拉开，同时将魔力沿视线推至物品表面。",
      "failure": "牵引线在中途断裂时，物品会沿原路弹回一小段后落地。若目标被他人踩住或卡在缝隙中，牵引线会从物品表面滑脱，施术者掌心会感到一阵空拉。",
      "counters": [
        "用脚踩住物品或用重物压住，牵引线便无法收紧。",
        "站到施术者与物品之间阻断视线，牵引线会立即消散。"
      ],
      "socialConsequences": "河谷集市上，摊贩允许顾客用此术取回掉入摊缝的钱袋，但要求先说明物品特征，避免误取邻摊货物。中陆城市公会大厅设有登记簿，记录取回物品的归属争议，防止有人借术侵占。琥珀海岸码头工人常用它捡回掉入船舱夹缝的工具，但港务规定若取回的是他人货物，必须当场交还并接受货损查验。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时牵引线容易中途断裂，物品常弹回原处附近。",
        "掌握稳定视线后，轻物可沿直线平稳返回手中。",
        "熟练者能绕开简单弯折路径，减少物品与地面的摩擦。",
        "更高熟练度使牵引线更细更韧，仍不能穿过实体障碍。"
      ]
    },
    {
      "id": "spell_space_06",
      "theory": "隔湿袋将魔力均匀铺展在密封袋口的内外夹层中，使水汽难以沿袋口纤维渗入。魔力不改变袋体材质，也不填补破洞，只让原有封口处的纤维间隙暂时收窄。施术者需能触摸袋口或通过相连的绳索感知其位置。袋内物品若本身潮湿，水汽仍会在袋内循环，无法被排出。",
      "casting": "双手捏住袋口两侧，拇指沿封口线来回按压三次，每次按压时将魔力从指尖送入纤维间隙，最后合掌轻拍袋口。",
      "failure": "魔力分布不匀时，袋口会局部鼓起，水汽从薄弱处渗入，在袋内壁形成细密水珠。若袋口有未察觉的裂口，隔湿层会沿裂口边缘卷曲脱落，发出轻微的撕裂声。",
      "counters": [
        "用干布反复擦拭袋口，可磨掉附着的隔湿魔力层。",
        "将袋口浸入流水，水压会从外侧冲开纤维间隙。"
      ],
      "socialConsequences": "河谷农户用此术保护种子袋和干草药，乡约鼓励在公共晒场互相施术，但要求先确认袋内没有他人寄存的贵重物品。中陆城市药铺学徒常为客人的药包加固封口，公会规定若因施术不当导致药材受潮，须按市价赔偿。琥珀海岸渔民依赖它保存盐和干粮，港务在货损纠纷中会检查袋口是否有隔湿痕迹，以判断货物是否在装船前已受潮。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时袋口局部渗水，内壁会出现细密水珠。",
        "掌握均匀按压后，封口处能维持整段航程的干燥。",
        "熟练者能按袋口纤维走向调整魔力，减少表面残留。",
        "更高熟练度使隔湿层更薄更匀，破洞仍会照常漏水。"
      ]
    }
  ]
}
